const CHALLENGE_PATTERN = /^[A-Za-z0-9_-]{1,200}$/;

function sameText(received, expected) {
  if (typeof received !== 'string' || typeof expected !== 'string' || received.length !== expected.length) {
    return false;
  }
  let difference = 0;
  for (let index = 0; index < expected.length; index++) {
    difference |= received.charCodeAt(index) ^ expected.charCodeAt(index);
  }
  return difference === 0;
}

function verification(json) {
  // Execução manual pelo gatilho "Show verify token for Meta": mostra o valor para o painel da Meta.
  if (json.query === undefined) {
    return { fromMeta: false, verifyToken: json.expectedToken };
  }
  const query = json.query ?? {};
  const challenge = query['hub.challenge'];
  const accepted =
    query['hub.mode'] === 'subscribe' &&
    typeof challenge === 'string' &&
    CHALLENGE_PATTERN.test(challenge) &&
    sameText(query['hub.verify_token'], json.expectedToken);
  if (!accepted) {
    console.log(JSON.stringify({ event: 'whatsapp_verification_rejected' }));
    return { fromMeta: true, status: 403, body: '' };
  }
  return { fromMeta: true, status: 200, body: challenge };
}

return $input.all().map((item) => ({ json: verification(item.json) }));

const BSUID = /^[A-Z]{2}\.[A-Za-z0-9.]{1,150}$/;
const DIGITS = /^[0-9]{1,30}$/;
const MAX_ID_LENGTH = 200;
const MAX_TEXT_LENGTH = 4096;
const MAX_NAME_LENGTH = 100;
const IGNORED_TYPES = ['reaction', 'system', 'request_welcome'];

function log(event, details = {}) {
  console.log(JSON.stringify({ event, ...details }));
}

function signatureMatches(json) {
  const header = json.headers?.['x-hub-signature-256'];
  const computed = json.computedSignature;
  if (typeof header !== 'string' || typeof computed !== 'string' || computed.length === 0) {
    return false;
  }
  const expected = `sha256=${computed}`;
  if (header.length !== expected.length) return false;
  let difference = 0;
  for (let index = 0; index < expected.length; index++) {
    difference |= header.charCodeAt(index) ^ expected.charCodeAt(index);
  }
  return difference === 0;
}

function text(value, maxLength) {
  return typeof value === 'string' && value.trim().length > 0 ? value.slice(0, maxLength) : null;
}

function matching(value, pattern) {
  return typeof value === 'string' && pattern.test(value) ? value : null;
}

function errorCodes(errors) {
  return (Array.isArray(errors) ? errors : []).map((error) => error?.code).filter(Number.isInteger);
}

function content(message) {
  if (message.type === 'text') {
    const body = text(message.text?.body, MAX_TEXT_LENGTH);
    if (body !== null) return { type: 'text', text: body, replyId: null };
  }
  if (message.type === 'interactive') {
    const reply = message.interactive?.button_reply ?? message.interactive?.list_reply;
    const replyId = text(reply?.id, MAX_ID_LENGTH);
    if (replyId !== null) return { type: 'reply', text: text(reply.title, MAX_TEXT_LENGTH), replyId };
  }
  return { type: 'unsupported', text: null, replyId: null };
}

function parseMessage(message, contacts, phoneNumberId) {
  if (IGNORED_TYPES.includes(message.type)) return null;
  const contact =
    contacts.find((candidate) => typeof message.from_user_id === 'string' && candidate?.user_id === message.from_user_id) ??
    (contacts.length === 1 ? contacts[0] : undefined);
  const messageId = text(message.id, MAX_ID_LENGTH);
  const leadId = matching(message.from_user_id ?? contact?.user_id, BSUID);
  if (messageId === null || leadId === null) {
    log('whatsapp_invalid_message', { phoneNumberId });
    return null;
  }
  const seconds = Number(message.timestamp);
  return {
    phoneNumberId,
    messageId,
    leadId,
    phone: matching(message.from ?? contact?.wa_id, DIGITS),
    name: text(contact?.profile?.name, MAX_NAME_LENGTH),
    ...content(message),
    receivedAt: new Date(Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : Date.now()).toISOString(),
  };
}

function parseChange(change) {
  // smb_message_echoes fica para a T020; history, smb_app_state_sync e account_update são descartados (D013).
  if (change?.field !== 'messages' || typeof change.value !== 'object' || change.value === null) return [];
  const value = change.value;
  const phoneNumberId = matching(value.metadata?.phone_number_id, DIGITS);
  if (phoneNumberId === null) {
    log('whatsapp_invalid_payload');
    return [];
  }
  for (const status of Array.isArray(value.statuses) ? value.statuses : []) {
    if (status?.status === 'failed') {
      log('whatsapp_failed_status', { phoneNumberId, errorCodes: errorCodes(status.errors) });
    }
  }
  if (Array.isArray(value.errors) && value.errors.length > 0) {
    log('whatsapp_webhook_error', { phoneNumberId, errorCodes: errorCodes(value.errors) });
  }
  const contacts = Array.isArray(value.contacts) ? value.contacts : [];
  return (Array.isArray(value.messages) ? value.messages : [])
    .filter((message) => typeof message === 'object' && message !== null)
    .map((message) => parseMessage(message, contacts, phoneNumberId))
    .filter((message) => message !== null);
}

function parseEvents(json) {
  if (!signatureMatches(json)) {
    log('whatsapp_invalid_signature');
    return [];
  }
  const body = json.body;
  if (body?.object !== 'whatsapp_business_account' || !Array.isArray(body.entry)) {
    log('whatsapp_unexpected_payload');
    return [];
  }
  return body.entry
    .flatMap((entry) => (Array.isArray(entry?.changes) ? entry.changes : []))
    .flatMap(parseChange);
}

return $input.all().flatMap((item) => parseEvents(item.json).map((json) => ({ json })));

function log(event, details = {}) {
  console.log(JSON.stringify({ event, ...details }));
}

function buildEvent(result, message) {
  if (Array.isArray(result.invalidConfigs) && result.invalidConfigs.length > 0) {
    log('client_configs_invalid', { folders: result.invalidConfigs });
  }
  if (result.found !== true) {
    log('whatsapp_unknown_client', { phoneNumberId: message.phoneNumberId, reason: result.reason ?? 'unknown' });
    return [];
  }
  return [
    {
      event: {
        clientId: result.config.id,
        channel: 'whatsapp',
        leadId: message.leadId,
        phone: message.phone,
        name: message.name,
        messageIds: [message.messageId],
        type: message.type,
        text: message.text,
        replyId: message.replyId,
        receivedAt: message.receivedAt,
      },
      config: result.config,
    },
  ];
}

return $input.all().flatMap((item, index) =>
  buildEvent(item.json, $('Is new message').itemMatching(index).json).map((json) => ({ json })),
);
